theorem strong_bijection_lipschitz {d : ℕ}
    {B K : Set (EuclideanSpace ℝ (Fin d))}
    (f : StrongBijection B) (hK : IsCompact K) (hKB : K ⊆ B) :
    ∃ L : ℝ, 1 ≤ L ∧ ∀ y ∈ K, ∀ z ∈ K,
      L⁻¹ * ‖y - z‖ ≤ ‖f.invFun y - f.invFun z‖ ∧
      ‖f.invFun y - f.invFun z‖ ≤ L * ‖y - z‖

